window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8ba88db5c3893244"]={"versions": [{"id": "FIG-8ba88db5c3893244", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm mit bedingter Verzweigung (<code>alt</code>-Fragment).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses bei der Meldung eines Überwachungspunktes (<em>Checkpoint</em>) durch eine Applikation an das Laufzeitüberwachungssystem unter Einbeziehung von Zugriffsvalidierung und sicherheitsrelevanter Anomalieerfassung.\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (AP R23-11), Zusammenspiel des funktionalen Sicherheitsclusters <em>Platform Health Management</em> (PHM) mit dem Security-Cluster <em>Intrusion Detection System Manager</em> (IdsM) sowie einer instanziierten <em>Adaptive Application</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure / Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>:Adaptive Application</code>: Prozessinstanz im User-Space, instrumentiert mit Checkpoints zur Kontrollfluss- und Lebendigkeitsüberwachung.\n</li><li><code>«aapFunctionalCluster» :Platform Health Management</code>: Zentraler Systemdienst zur Überwachung von <em>Alive-</em>, <em>Deadline-</em> und <em>Logical Supervisions</em>.\n</li><li><code>«aapFunctionalCluster» :Intrusion Detection System Manager</code>: Zentraler Plattformdienst zur Erfassung, Filterung und Weiterleitung von Security-Ereignissen (<em>Security Events</em>).\n</li></ul>\n</li><li><strong>Operationen &amp; Schnittstellen:</strong>\n<ul class=\"fig-list\"><li><code>ReportCheckpoint()</code>: Interaktionsaufruf (IPC/API, i. d. R. <code>ara::phm</code>) von der Applikation an das PHM mit Übergabe der Checkpoint-ID.\n</li><li><code>checkAccess()</code>: PHM-interner Validierungsaufruf zur Prüfung der Prozess-Identität und Sendeberechtigung gegen die hinterlegte Zugriffs- bzw. Sicherheitskonfiguration (Identity &amp; Access Management).\n</li><li><code>handleReportedCheckpoint()</code>: PHM-interne Routine zur Aktualisierung der Überwachungsmodi (z. B. Hochzählen von Alive-Countern, Timer-Stopp/Start bei Deadlines, Graph-Traversierung bei Logical Supervisions).\n</li><li><code>ReportEvent()</code>: Standardisierte API-Interaktion (<code>ara::idsm</code>) zur Übergabe eines definierten Security Events (SEv) an den IdsM bei unautorisiertem Zugriff.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Die <code>:Adaptive Application</code> erreicht im Kontrollfluss einen Messpunkt und ruft synchron/asynchron <code>ReportCheckpoint()</code> auf dem <code>:Platform Health Management</code> auf.\n</li><li><strong>Autorisierungsprüfung:</strong> PHM führt unverzüglich die interne Routine <code>checkAccess()</code> aus, um zu verifizieren, ob der aufrufende Kontext (Prozess/UID/PID) für diese spezifische Checkpoint-ID autorisiert ist.\n</li><li><strong>Bedingte Verzweigung (<code>alt</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Pfad <code>[access granted]</code>:</strong> Bei erfolgreicher Autorisierung ruft PHM intern <code>handleReportedCheckpoint()</code> auf. Der Status der zugeordneten Supervisions (Alive/Deadline/Logical) wird aktualisiert; keine Benachrichtigung externer Security-Cluster.\n</li><li><strong>Pfad <code>[access denied]</code>:</strong> Ist der Prozess nicht autorisiert (z. B. Prozess-Spoofing, korrumpierter Kontext), bricht PHM die Checkpoint-Auswertung ab und meldet den Vorfall via <code>ReportEvent()</code> an den <code>:Intrusion Detection System Manager</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest- &amp; Konfigurationspflichten:</strong>\n<ul class=\"fig-list\"><li>Checkpoints müssen im ARXML-Datenmodell (<code>HealthChannelAction</code>, <code>SupervisedEntity</code>, <code>Checkpoint</code>) modelliert und eindeutig einer Applikation bzw. einem Executable zugeordnet sein.\n</li><li>Berechtigungen müssen in den Zugriffsregeln (IAM/Security Profiles) des PHM gepflegt sein; Diskrepanzen zwischen Applikationscode und Manifest führen unmittelbar zu <code>access denied</code>.\n</li></ul>\n</li><li><strong>Einfluss auf die Applikationsentwicklung:</strong>\n<ul class=\"fig-list\"><li>Applikationen dürfen Checkpoint-IDs nicht generisch oder dynamisch wählen; unzulässige oder nicht zugeordnete IDs provozieren Security-Meldungen im System.\n</li><li>Instrumentierung mit <code>ReportCheckpoint()</code> muss strikt deterministisch erfolgen, um Timing- und Kontrollflussfehler zu vermeiden.\n</li></ul>\n</li><li><strong>Einfluss auf Plattform-/Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Das PHM muss eine performante Prozessauthentifizierung bereitstellen (z. B. via Peer-Credentials über Unix Domain Sockets), damit <code>checkAccess()</code> minimalen Overhead auf die Echtzeitausführung hat.\n</li><li>Für den IdsM muss eine dedizierte <em>Security Event Definition</em> (SEv) für fehlgeschlagene Checkpoint-Zugriffe parametriert sein, inklusive Context-Data-Payload (z. B. fehlerhafte ID, anfragende Prozess-ID).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0aaa2ebc8b17d424", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm mit bedingter Verzweigung (<code>alt</code>-Fragment).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses bei der Meldung eines Überwachungspunktes (<em>Checkpoint</em>) durch eine Applikation an das Laufzeitüberwachungssystem unter Einbeziehung von Zugriffsvalidierung und sicherheitsrelevanter Anomalieerfassung.\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (AP R23-11), Zusammenspiel des funktionalen Sicherheitsclusters <em>Platform Health Management</em> (PHM) mit dem Security-Cluster <em>Intrusion Detection System Manager</em> (IdsM) sowie einer instanziierten <em>Adaptive Application</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure / Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>:Adaptive Application</code>: Prozessinstanz im User-Space, instrumentiert mit Checkpoints zur Kontrollfluss- und Lebendigkeitsüberwachung.\n</li><li><code>«aapFunctionalCluster» :Platform Health Management</code>: Zentraler Systemdienst zur Überwachung von <em>Alive-</em>, <em>Deadline-</em> und <em>Logical Supervisions</em>.\n</li><li><code>«aapFunctionalCluster» :Intrusion Detection System Manager</code>: Zentraler Plattformdienst zur Erfassung, Filterung und Weiterleitung von Security-Ereignissen (<em>Security Events</em>).\n</li></ul>\n</li><li><strong>Operationen &amp; Schnittstellen:</strong>\n<ul class=\"fig-list\"><li><code>ReportCheckpoint()</code>: Interaktionsaufruf (IPC/API, i. d. R. <code>ara::phm</code>) von der Applikation an das PHM mit Übergabe der Checkpoint-ID.\n</li><li><code>«aapInformative» checkAccess()</code>: PHM-interner Validierungsaufruf zur Prüfung der Prozess-Identität und Sendeberechtigung gegen die hinterlegte Zugriffs- bzw. Sicherheitskonfiguration (Identity &amp; Access Management), explizit mit Stereotyp <code>«aapInformative»</code> als informativ gekennzeichnet.\n</li><li><code>«aapInformative» handleReportedCheckpoint()</code>: PHM-interne Routine zur Aktualisierung der Überwachungsmodi (z. B. Hochzählen von Alive-Countern, Timer-Stopp/Start bei Deadlines, Graph-Traversierung bei Logical Supervisions), explizit mit Stereotyp <code>«aapInformative»</code> als informativ gekennzeichnet.\n</li><li><code>ReportEvent()</code>: Standardisierte API-Interaktion (<code>ara::idsm</code>) zur Übergabe eines definierten Security Events (SEv) an den IdsM bei unautorisiertem Zugriff.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Die <code>:Adaptive Application</code> erreicht im Kontrollfluss einen Messpunkt und ruft synchron/asynchron <code>ReportCheckpoint()</code> auf dem <code>:Platform Health Management</code> auf.\n</li><li><strong>Autorisierungsprüfung:</strong> PHM führt unverzüglich die interne Routine <code>checkAccess()</code> aus, um zu verifizieren, ob der aufrufende Kontext (Prozess/UID/PID) für diese spezifische Checkpoint-ID autorisiert ist.\n</li><li><strong>Bedingte Verzweigung (<code>alt</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Pfad <code>[access granted]</code>:</strong> Bei erfolgreicher Autorisierung ruft PHM intern <code>handleReportedCheckpoint()</code> auf. Der Status der zugeordneten Supervisions (Alive/Deadline/Logical) wird aktualisiert; keine Benachrichtigung externer Security-Cluster.\n</li><li><strong>Pfad <code>[access denied]</code>:</strong> Ist der Prozess nicht autorisiert (z. B. Prozess-Spoofing, korrumpierter Kontext), bricht PHM die Checkpoint-Auswertung ab und meldet den Vorfall via <code>ReportEvent()</code> an den <code>:Intrusion Detection System Manager</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest- &amp; Konfigurationspflichten:</strong>\n<ul class=\"fig-list\"><li>Checkpoints müssen im ARXML-Datenmodell (<code>HealthChannelAction</code>, <code>SupervisedEntity</code>, <code>Checkpoint</code>) modelliert und eindeutig einer Applikation bzw. einem Executable zugeordnet sein.\n</li><li>Berechtigungen müssen in den Zugriffsregeln (IAM/Security Profiles) des PHM gepflegt sein; Diskrepanzen zwischen Applikationscode und Manifest führen unmittelbar zu <code>access denied</code>.\n</li></ul>\n</li><li><strong>Einfluss auf die Applikationsentwicklung:</strong>\n<ul class=\"fig-list\"><li>Applikationen dürfen Checkpoint-IDs nicht generisch oder dynamisch wählen; unzulässige oder nicht zugeordnete IDs provozieren Security-Meldungen im System.\n</li><li>Instrumentierung mit <code>ReportCheckpoint()</code> muss strikt deterministisch erfolgen, um Timing- und Kontrollflussfehler zu vermeiden.\n</li></ul>\n</li><li><strong>Einfluss auf Plattform-/Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Das PHM muss eine performante Prozessauthentifizierung bereitstellen (z. B. via Peer-Credentials über Unix Domain Sockets), damit <code>checkAccess()</code> minimalen Overhead auf die Echtzeitausführung hat.\n</li><li>Für den IdsM muss eine dedizierte <em>Security Event Definition</em> (SEv) für fehlgeschlagene Checkpoint-Zugriffe parametriert sein, inklusive Context-Data-Payload (z. B. fehlerhafte ID, anfragende Prozess-ID).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8ba88db5c3893244", "to": "FIG-0aaa2ebc8b17d424", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Interne Methode <code>checkAccess()</code>:</strong> Ergänzung des Stereotyps <code>«aapInformative»</code> über dem Methodenaufruf auf der Lebenslinie <code>:Platform Health Management</code>.\n</li><li><strong>Interne Methode <code>handleReportedCheckpoint()</code>:</strong> Ergänzung des Stereotyps <code>«aapInformative»</code> über dem Methodenaufruf auf der Lebenslinie <code>:Platform Health Management</code> innerhalb des <code>[access granted]</code>-Zweigs.\n</li></ul>"}]};
